E("up-cm-yuva-yojana", name="Mukhyamantri Yuva Udyami Vikas Abhiyan – CM YUVA (Uttar Pradesh)", short="Interest-free, collateral-free loan up to ₹5 lakh and 10% margin money subsidy for young entrepreneurs of UP.", tag="UP · Young entrepreneurs", ministry="MSME Department, Uttar Pradesh",
 facts=[("Age","21 to 40 years"),("Loan","Up to ₹5 lakh, interest-free"),("Subsidy","10% margin money subsidy on project cost"),("Portal","msme.up.gov.in")],
 about="CM YUVA (Mukhyamantri Yuva Udyami Vikas Abhiyan) gives young people in Uttar Pradesh interest-free and collateral-free loans to start their own business. In every district, experts help from application to running the business. Applications are made on the UP MSME portal.",
 benefits=["Interest-free loan up to ₹5 lakh (as per UP MSME portal)","Without collateral","10% margin money subsidy on project cost, which eases the initial burden","After repaying the first loan a larger loan may be available in the next stage (confirm the amount with portal/bank)","District-level experts/guidance and ready project reports"],
 elig=["Resident of Uttar Pradesh","Age 21 to 40 years","At least 8th pass, or training/certificate under a government scheme or skill mission, a diploma or a degree","Has not taken interest or capital subsidy under any Central/State scheme before (except PM SVANidhi, as per bank)","Wanting to start a new enterprise"],
 notelig=["Applicants below 21 or above 40 years (some reports mention the age limit changing, confirm on the portal)","Those who do not meet the eligibility conditions","Those who have not repaid an earlier loan"],
 docs=["Aadhaar card","Residence proof","Educational qualification / training or skill certificate","Bank account details","Project report / business plan","Other documents asked by the bank"],
 steps=["Go to msme.up.gov.in and look for the CM YUVA application","Register and choose or upload your business idea/project report","Fill the online application and submit documents","After bank/department checks the loan is sanctioned","Take guidance from the district expert"],
 link_label="msme.up.gov.in – official portal", helpline="",
 faq=[("What age is required for CM YUVA?","21 to 40 years as per the UP MSME portal. Some reports mention the limit changing, so confirm on the portal before applying."),("Is it really interest-free?","The portal describes an interest-free, collateral-free loan up to ₹5 lakh. The bank's own conditions and checks still apply."),("What is margin money subsidy?","A 10% subsidy on project cost that reduces the initial capital burden. Take details from the portal/bank.")],
 note="Different sources give different loan amounts and age limits (some banks quote lower stage-wise limits). The figures here are taken from the UP MSME portal, but still confirm on msme.up.gov.in before applying.")
